let caller;
try { caller = $('Провери заявката').first().json; } catch { caller = null; }
const scopes = caller?.router_context?.permission_context?.scopes;
if (caller?.route !== 'agent' || !Array.isArray(scopes) || !scopes.some(s => s === 'module:read' || s === 'finance:status:read'))
  return JSON.stringify({status:'unavailable',code:'SCOPE_REQUIRED'});
let input;
try { input = typeof query === 'string' ? JSON.parse(query) : query; } catch { input = null; }
const invalid = () => JSON.stringify({status:'unavailable',code:'INVALID_TARGET'});
if (!input || !/^[A-Z]{3}$/.test(input.currency) || !/^[1-9]\d{0,14}$/.test(input.capital_minor) ||
    !/^(0|[1-9]\d{0,14})$/.test(input.profit_minor) || !Number.isInteger(input.days) || input.days<1 || input.days>366) return invalid();
const capital = BigInt(input.capital_minor), goal = BigInt(input.profit_minor);
const percentHundredths = (goal*10000n + capital/2n) / capital;
return JSON.stringify({status:'ok',source:'shark-ai-target-arithmetic',currency:input.currency,days:input.days,
  capital_minor:capital.toString(),target_profit_minor:goal.toString(),required_return_percent:(percentHundredths/100n).toString()+'.'+(percentHundredths%100n).toString().padStart(2,'0'),
  interpretation:'Потребителска цел за целия период. Прогнозата изисква потвърдени средства и история след такси.',timestamp:new Date().toISOString()});
